import {mountPaperFigure} from './paper-results.js';
import {mountAdvancedLab} from './advanced-labs.js';
import * as S from './science.js';
import{colors,esc,fmt,plot,legend,barPlot}from'./viz.js';
const slider=(label,id,min,max,step,value)=>`<div class="control"><label for="${id}">${label}<output for="${id}">${value}</output></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;
const select=(label,id,options,value)=>`<div class="control"><label for="${id}">${label}</label><select id="${id}">${options.map(([v,l])=>`<option value="${v}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></div>`;
const metrics=items=>items.map(([name,value])=>`<div class="lab-metric"><span>${esc(name)}</span><strong>${typeof value==='number'?fmt(value):esc(value)}</strong></div>`).join('');
const shell=(title,controls,body='',caption='Teaching simulation · calculated in this browser.')=>`<div class="lab"><div class="lab-heading"><strong>${title}</strong><span>LIVE EXPERIMENT</span></div><div class="lab-controls">${controls}</div><div class="lab-body">${body}</div><div class="lab-metrics"></div><div class="lab-caption">${caption}</div></div>`;
const bindInputs=(host,update)=>host.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{const output=host.querySelector(`output[for="${el.id}"]`);if(output)output.value=el.value;update();}));
const uniform=x=>x.map(()=>1/x.length);

function weights(host){const x=[-3,-2,-1,0,1,2,3,4];host.innerHTML=shell('A weighted particle distribution','',`<div id="weight-plot"></div>`,'Teaching simulation · sliders set unnormalized positive masses. Circle area is proportional to normalized weight. The dashed line is the weighted mean.');host.querySelector('.lab-controls').outerHTML=`<div class="weight-sliders">${x.map((v,i)=>slider(`x = ${v}`,`weight-${i}`,1,100,1,i===5?45:15)).join('')}</div>`;
 function update(){const masses=x.map((_,i)=>+host.querySelector(`#weight-${i}`).value),total=S.sum(masses),w=masses.map(v=>v/total),m=S.scalarMoments(x,w);host.querySelector('#weight-plot').innerHTML=plot({series:[{name:'Particle probability',type:'scatter',points:x.map((v,i)=>[v,w[i]]),sizes:w.map(v=>Math.sqrt(v)*22),color:colors[0]}],xLabel:'Particle position x',yLabel:'Normalized probability mass',yDomain:[0,1],xDomain:[-3.5,4.5],marker:m.mean,height:265});host.querySelector('.lab-metrics').innerHTML=metrics([['Weighted mean',m.mean],['Variance',m.variance],['ESS out of 8',S.ess(w)],['Largest weight',Math.max(...w)]]);}
 bindInputs(host,update);update();}

function classical(host){let seed=43,batch=null;host.innerHTML=shell('Sample particle ancestors',select('Method','class-method',[['multinomial','Multinomial'],['systematic','Systematic'],['stratified','Stratified'],['residual','Residual']],'systematic')+slider('Right-mode mass','class-mass',.1,.9,.05,.65)+select('Input order','class-order',[['interleaved','Interleaved modes'],['sorted','Sorted by position']],'interleaved')+'<button class="button secondary small" id="draw">New draw</button><button class="button primary small" id="repeat">Repeat 500</button>',`<p class="cdf-label">CDF intervals · width = probability mass</p><div id="cdf"></div><p class="cdf-label">Selected ancestor positions</p><div id="ancestors"></div><div id="class-plot"></div><div class="lab-status" id="batch-status">Repeat the draw to estimate resampling variation.</div>`,'Teaching simulation · N=8. Reordering changes the CDF while keeping the input probability measure fixed. Colors identify the position of each ancestor; the bar widths show its probability.');
 function problem(){const mass=+host.querySelector('#class-mass').value;let x=[-3,3,-2.8,2.8,-2.6,2.6,-2.4,2.4],w=x.map(v=>v>0?mass/4:(1-mass)/4);if(host.querySelector('#class-order').value==='sorted'){const indices=x.map((_,i)=>i).sort((a,b)=>x[a]-x[b]);w=indices.map(i=>w[i]);x=indices.map(i=>x[i]);}return{x,w,method:host.querySelector('#class-method').value};}
 function update(){const{x,w,method}=problem(),indices=S.sampleIndices(w,method,S.rng(seed)),counts=x.map((_,i)=>indices.filter(j=>j===i).length),target=S.scalarMoments(x,w),estimate=S.mean(indices.map(i=>x[i]));host.querySelector('#cdf').innerHTML=`<div class="cdf-bar">${w.map((v,i)=>`<div class="cdf-block" style="width:${100*v}%;background:${colors[i]}"><span>${x[i]}</span></div>`).join('')}</div>`;host.querySelector('#ancestors').innerHTML=`<div class="ancestor-strip">${indices.map(i=>`<span style="background:${colors[i]}">${x[i]}</span>`).join('')}</div>`;host.querySelector('#class-plot').innerHTML=plot({series:[{name:'Target mass',points:x.map((v,i)=>[v,w[i]]),type:'scatter',radius:5,color:colors[1]},{name:'Output mass (copies/8)',points:x.map((v,i)=>[v,counts[i]/8]),type:'scatter',radius:4,color:colors[0]}],xLabel:'Particle position',yLabel:'Probability mass',yDomain:[0,.5],height:240});host.querySelector('.lab-metrics').innerHTML=metrics([['Target mean',target.mean],['Output mean',estimate],['One-draw mean error',Math.abs(estimate-target.mean)],['Repeated mean MSE',batch?.mse??'Run 500 draws']]);host.querySelector('#batch-status').textContent=batch?`500 draws · mean estimator bias ${fmt(batch.bias)} · mean offspring-count variance ${fmt(batch.variance)} · seed ${seed}.`:'Repeat the draw to estimate resampling variation.';}
 bindInputs(host,()=>{batch=null;update();});host.querySelector('#draw').onclick=()=>{seed++;update();};host.querySelector('#repeat').onclick=()=>{const{x,w,method}=problem(),random=S.rng(seed),target=S.scalarMoments(x,w).mean,estimates=[],allCounts=[];for(let j=0;j<500;j++){const a=S.sampleIndices(w,method,random);estimates.push(S.mean(a.map(i=>x[i])));allCounts.push(x.map((_,i)=>a.filter(k=>k===i).length));}const means=x.map((_,i)=>S.mean(allCounts.map(c=>c[i])));batch={mse:S.mean(estimates.map(v=>(v-target)**2)),bias:S.mean(estimates)-target,variance:S.mean(x.map((_,i)=>S.mean(allCounts.map(c=>(c[i]-means[i])**2))))};update();};update();}

function ellipse(mom){const root=S.root2(mom.cov);return Array.from({length:81},(_,i)=>{const t=2*Math.PI*i/80,v=S.rowMultiply([1.96*Math.cos(t),1.96*Math.sin(t)],root);return v.map((a,j)=>a+mom.mean[j]);});}
function eigen(host){let stage='input';host.innerHTML=shell('The affine transformation',slider('Weight tilt','eigen-tilt',-1.5,1.5,.1,.7)+slider('Input correlation','eigen-rho',-.9,.9,.1,.6),'<div id="eigen-plot"></div><div class="lab-status" id="eigen-status"></div>','Teaching simulation · N=96, d=2. The dashed target outline is a mean ± 1.96-standard-deviation shape guide. It is not a 95% joint credible region. Stage axes have the same scale.');const controls=host.querySelector('.lab-controls');controls.insertAdjacentHTML('afterend',`<div class="stage-buttons" role="group" aria-label="Transformation stage">${[['input','1 · Input'],['z','2 · Center'],['white','3 · Whiten'],['colored','4 · Color'],['y','5 · Shift']].map(([v,l])=>`<button class="stage-button ${v===stage?'active':''}" data-stage="${v}" aria-pressed="${v===stage}">${l}</button>`).join('')}</div>`);
 function update(){const rho=+host.querySelector('#eigen-rho').value,tilt=+host.querySelector('#eigen-tilt').value,random=S.rng(91),x=Array.from({length:96},()=>{const a=S.normal(random),b=S.normal(random);return[a,rho*a+Math.sqrt(1-rho*rho)*b];}),w=S.softmax(x.map(p=>tilt*p[0])),result=S.eigen2(x,w),points=stage==='input'?x:result[stage],mom=S.moments(points),covError=Math.sqrt(S.sum(mom.cov.flatMap((row,i)=>row.map((v,j)=>(v-result.target.cov[i][j])**2)))),muError=Math.hypot(...mom.mean.map((v,i)=>v-result.target.mean[i]));host.querySelector('#eigen-plot').innerHTML=plot({series:[{name:'Target covariance outline',points:ellipse(result.target),color:'#9ba8ae',dashed:true},{name:stage==='input'?'Weighted input':'Equal-weight transformed cloud',points,type:'scatter',color:stage==='input'?colors[1]:colors[0],sizes:stage==='input'?w.map(v=>Math.sqrt(v)*24):undefined,radius:3}],xLabel:'Coordinate 1',yLabel:'Coordinate 2',xDomain:[-8,8],yDomain:[-4,4],height:395});host.querySelector('.lab-metrics').innerHTML=metrics([['Equal-weight mean x',mom.mean[0]],['Equal-weight variance x',mom.cov[0][0]],['Target mean x',result.target.mean[0]],['Target variance x',result.target.cov[0][0]]]);host.querySelector('#eigen-status').innerHTML=stage==='y'?`<span class="good">Final moment check:</span> mean error ${fmt(muError)}; covariance Frobenius error ${fmt(covError)}.`:stage==='white'?`Whitened covariance: [${fmt(mom.cov[0][0])}, ${fmt(mom.cov[0][1])}; ${fmt(mom.cov[1][0])}, ${fmt(mom.cov[1][1])}].`:'Stage statistics use equal weights. The input circle sizes show the target weights.';}
 bindInputs(host,update);host.querySelectorAll('[data-stage]').forEach(button=>button.onclick=()=>{stage=button.dataset.stage;host.querySelectorAll('[data-stage]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',b===button);});update();});update();}

function histogram(x,w,lo,hi,bins=44){const values=Array(bins).fill(0),width=(hi-lo)/bins;x.forEach((p,i)=>{const b=Math.floor((p-lo)/width);if(b>=0&&b<bins)values[b]+=w[i]/width;});return values.map((v,i)=>[lo+(i+.5)*width,v]);}
function mixture(host){let seed=41;host.innerHTML=shell('Same moments, different shape',slider('Right-mode mass','mix-mass',.1,.9,.05,.65)+slider('Mode separation','mix-separation',1,4.5,.25,3)+select('Output method','mix-method',[['eigen','Eigen affine'],['multinomial','Multinomial draw'],['gaussian','Gaussian draw']],'eigen')+'<button class="button secondary small" id="mix-draw">New seed</button>','<div id="mix-plot"></div><div class="lab-status" id="mix-status"></div>','Teaching simulation · N=128. W1 uses exact empirical CDF integration. MMD² uses an exact 1D Gaussian-kernel sum with bandwidth equal to target standard deviation; the main benchmark uses an RFF approximation.');
 function update(){const mass=+host.querySelector('#mix-mass').value,separation=+host.querySelector('#mix-separation').value,method=host.querySelector('#mix-method').value,{x,w}=S.mixture(128,separation,mass,seed),target=S.scalarMoments(x,w),random=S.rng(seed+500),y=method==='eigen'?S.eigen1(x,w):method==='multinomial'?S.sampleIndices(w,'multinomial',random).map(i=>x[i]):x.map(()=>target.mean+Math.sqrt(target.variance)*S.normal(random)),output=S.scalarMoments(y),bound=Math.max(separation+2,...y.map(Math.abs)),inputHist=histogram(x,w,-bound,bound),outputHist=histogram(y,uniform(y),-bound,bound);host.querySelector('#mix-plot').innerHTML=plot({series:[{name:'Weighted input density',points:inputHist,type:'bar',color:colors[1]},{name:'Equal-weight output density',points:outputHist,color:colors[0],dots:false}],xLabel:'Particle position',yLabel:'Histogram density',xDomain:[-bound,bound],yDomain:[0,Math.max(...inputHist.map(p=>p[1]),...outputHist.map(p=>p[1]))*1.15],height:310})+legend([['Weighted input',colors[1]],['Output',colors[0]]]);host.querySelector('.lab-metrics').innerHTML=metrics([['Mean error',Math.abs(output.mean-target.mean)],['Variance error',Math.abs(output.variance-target.variance)],['Exact 1D W1',S.wasserstein1(x,w,y)],['Exact kernel MMD²',S.mmd2(x,w,y)],['Right-halfspace mass',y.filter(v=>v>0).length/y.length]]);host.querySelector('#mix-status').textContent=method==='eigen'?'The affine map matches two moments. Its equally weighted particles can still assign the wrong mass or location to a mode.':method==='gaussian'?'This draws from a Gaussian with the target moments. A finite random draw does not exactly match those moments, and a Gaussian does not retain two modes.':'This copies ancestors. A single draw has Monte Carlo error; conditional unbiasedness refers to repeated draws.';}
 bindInputs(host,update);host.querySelector('#mix-draw').onclick=()=>{seed++;update();};update();}

function gradient(host){host.innerHTML=shell('Which derivative are we checking?',slider('Log-weight tilt θ','gradient-theta',-.9,.9,.03,.24)+select('Test function','gradient-function',[['sin','sin(x) · nonlinear'],['square','x² · moment matched']],'sin')+select('Finite-difference step h','gradient-step',[['0.00001','0.00001'],['0.0001','0.0001'],['0.001','0.001'],['0.01','0.01']],'0.001'),'<div id="gradient-value-plot"></div><div id="gradient-slope-plot"></div><div class="lab-status" id="gradient-status"></div>','Teaching simulation · deterministic, one-dimensional affine map. “Analytic” means a direct derivative of this scalar construction, not a PyTorch/JAX backward call. Fixed particles and softmax weights; no PF likelihood is evaluated here.');
 function update(){const theta=+host.querySelector('#gradient-theta').value,fn=host.querySelector('#gradient-function').value,h=+host.querySelector('#gradient-step').value,current=S.gradientToy(theta,fn),finite=(S.gradientToy(theta+h,fn).value-S.gradientToy(theta-h,fn).value)/(2*h),grid=Array.from({length:61},(_,i)=>-.9+1.8*i/60),values=grid.map(t=>S.gradientToy(t,fn));host.querySelector('#gradient-value-plot').innerHTML=plot({series:[{name:'Original weighted objective F',points:grid.map((t,i)=>[t,values[i].original]),color:colors[1]},{name:'Affine surrogate G',points:grid.map((t,i)=>[t,values[i].value]),color:colors[0],dashed:true}],xLabel:'Weight tilt θ',yLabel:'Objective value',marker:theta,height:255})+legend([['Original F',colors[1]],['Affine surrogate G (dashed)',colors[0]]]);host.querySelector('#gradient-slope-plot').innerHTML=plot({series:[{name:'Original derivative F′',points:grid.map((t,i)=>[t,values[i].originalGradient]),color:colors[1]},{name:'Surrogate derivative G′',points:grid.map((t,i)=>[t,values[i].gradient]),color:colors[0],dashed:true}],xLabel:'Weight tilt θ',yLabel:'First derivative',marker:theta,height:255});host.querySelector('.lab-metrics').innerHTML=metrics([['Original derivative F′',current.originalGradient],['Surrogate derivative G′',current.gradient],['Finite difference of G',finite],['Derivative check |G′−FD|',Math.abs(current.gradient-finite)],['Target error |G′−F′|',Math.abs(current.gradient-current.originalGradient)]]);host.querySelector('#gradient-status').innerHTML=`<span class="good">Implementation check:</span> analytic G′ and finite differences of G should agree. <b>Target check:</b> ${fn==='square'?'x² is fixed by moment matching, so F and G agree here.':'A mismatch with F′ can remain because G is a different objective.'}`;}
 bindInputs(host,update);update();}

function filter(host){let seed=43,result;host.innerHTML=shell('A particle filter and exact Kalman reference',select('Particle count','pf-n',[[32,'32'],[128,'128'],[512,'512']],'128')+select('Resampler','pf-method',[['systematic','Systematic'],['multinomial','Multinomial'],['eigen','Eigen affine'],['none','No resampling']],'systematic')+slider('Observation noise SD r','pf-noise',.2,1.6,.1,.8)+'<button class="button secondary small" id="pf-new">New dataset</button>','<div id="pf-plot"></div><div id="pf-ess"></div>','Teaching simulation · 40 steps and ESS threshold N/2. The shaded band is a Gaussian approximation to the particle posterior. This browser run is separate from the recorded benchmark grid.');host.querySelector('.lab-controls').insertAdjacentHTML('afterend',`<div class="lab-controls">${slider('Inspect time step','pf-time',1,40,1,40)}</div>`);
 function paint(){const t=+host.querySelector('#pf-time').value,n=+host.querySelector('#pf-n').value,points=(a)=>a.slice(0,t).map((v,i)=>[i+1,v]),upper=result.means.map((m,i)=>m+1.96*Math.sqrt(result.variances[i])),lower=result.means.map((m,i)=>m-1.96*Math.sqrt(result.variances[i]));host.querySelector('#pf-plot').innerHTML=plot({series:[{name:'Particle mean ± 1.96 SD',type:'band',points:points(upper).concat(points(lower).reverse()),color:colors[0]},{name:'Hidden truth',points:points(result.truth),color:'#596d7a',dashed:true},{name:'Observations',points:points(result.observations),color:'#aab3bc',type:'scatter',radius:2.4},{name:'Exact Kalman mean',points:points(result.exact.means),color:colors[1]},{name:'Particle posterior mean',points:points(result.means),color:colors[0]}],xLabel:'Time step',yLabel:'State position',xDomain:[1,40],height:305})+legend([['Hidden truth (dashed)','#596d7a'],['Observations','#aab3bc'],['Exact Kalman',colors[1]],['Particle mean / band',colors[0]]]);host.querySelector('#pf-ess').innerHTML=plot({series:[{name:'ESS',points:points(result.effective),color:colors[0],dots:true,radius:2.2},{name:'Resampling threshold',points:[[1,n/2],[40,n/2]],color:'#b2987a',dashed:true}],xLabel:'Time step',yLabel:'ESS before resampling',xDomain:[1,40],yDomain:[0,n],height:200});host.querySelector('.lab-metrics').innerHTML=metrics([['40-step state RMSE',result.rmse],['Posterior mean RMSE vs Kalman',result.posteriorError],['40-step log-likelihood error',result.loglik-result.exact.loglik],['Resampling events',result.flags.filter(Boolean).length],['ESS at inspected step',result.effective[t-1]]]);}
 function update(){result=S.filterToy(+host.querySelector('#pf-n').value,host.querySelector('#pf-method').value,+host.querySelector('#pf-noise').value,seed);paint();}
 host.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{const out=host.querySelector(`output[for="${el.id}"]`);if(out)out.value=el.value;if(el.id==='pf-time')paint();else update();}));host.querySelector('#pf-new').onclick=()=>{seed++;update();};update();}

const providerNames={custom:'Local baselines',particles:'particles',stonesoup:'Stone Soup',pfjax:'PFJAX',cuthbert:'Cuthbert',pydpf:'PyDPF',torchfilter:'Torchfilter',filterflow:'FilterFlow',julia:'Resamplings.jl'};
const resultSchemas={
 static:{table:'static_summary',label:'Static clouds',caseKey:'cloud',cases:[['mixture','Gaussian mixture'],['gaussian','Gaussian'],['fixed','Fixed cloud'],['skewed','Skewed weights']],metrics:[['sliced_w1_mean','Sliced W1'],['covariance_error_mean','Covariance Frobenius error'],['mean_error_mean','Mean error'],['rff_mmd2_mean','RFF MMD²'],['mode_coverage_mean','Mode coverage'],['mode_mass_error_mean','Mode mass error'],['estimator_mse_sin_mean','sin expectation MSE']],caption:'Shared static suite · x-axis is serial forward integration time including adapter overhead. Lower error is better; mode coverage is better when higher. Intervals are 95% Student-t intervals for repeated resampling on a fixed cloud.'},
 filter:{table:'filter_summary',label:'Full filters',caseKey:'model',cases:[['linear','Linear Gaussian'],['ungm','UNGM'],['volatility','Stochastic volatility'],['bearing','Bearing-only tracking']],metrics:[['rmse_mean','State / position RMSE'],['coverage95_mean','Nominal 95% region coverage'],['conditional_loglik_variance','Conditional likelihood variance'],['mean_ess_fraction_mean','Mean ESS fraction'],['recovered_mean','Recovery fraction (bearing)']],caption:'Shared filtering suite · 95% intervals cluster by observation dataset (up to 10). Coverage targets 0.95; higher alone is not sufficient. Expensive methods have one PF seed per dataset, so conditional likelihood variance is unavailable.'},
 gradient:{table:'native_gradients',label:'Likelihood gradients',metrics:[['gradient_bias','Gradient bias norm'],['gradient_variance','Total gradient variance'],['gradient_mse','Gradient MSE'],['loglik_bias','Signed log-likelihood bias']],caption:'Native Cuthbert and PyTorch comparison · same saved linear Gaussian observations; exact Kalman derivatives. Bias norms and MSE are lower-is-better. Log-likelihood bias is signed, so inspect its distance from zero. No uncertainty interval is included in these summaries.'},
 learning:{table:'learning_summary',label:'Scale fitting',metrics:[['parameter_absolute_error_mean','Absolute scale error'],['mle_reference_error_mean','Scale error vs grid-reference fit'],['score_rmse','Likelihood-score RMSE']],caption:'Shared volatility learning · 10 independent datasets, N=128, scale grid {0.6,0.8,1,1.2,1.4}. The grid-filter reference is approximate. These results do not establish continuous optimizer convergence.'},
 native:{table:'particles_native_summary',label:'Native models',caseKey:'model',cases:[['linear','Native linear Gaussian'],['ungm','Native Gordon / UNGM'],['volatility','Native StochVol'],['bearing','Native BearingsOnly']],metrics:[['rmse_mean','State / position RMSE'],['kalman_mean_rmse','Posterior mean RMSE vs Kalman'],['kalman_variance_rmse','Posterior variance RMSE vs Kalman']],caption:'Native particles models · unmodified upstream defaults, 50 steps, 10 datasets × 3 PF seeds. This is a different model/data layer from the shared suite. Displayed standard deviations are descriptive; no clustered confidence interval is included here.'}
};
async function results(host,loadData){let data,tab='static';host.innerHTML='<div class="lab"><div class="lab-heading"><strong>Measured results explorer</strong><span>RECORDED DATA</span></div><p class="result-data-note" role="status">Loading the measured summaries…</p></div>';try{data=await loadData();}catch(error){if(host.isConnected)host.innerHTML=`<div class="result-error">The recorded results could not load. The lessons and live labs still work. <button class="button secondary small" id="retry-results">Retry</button></div>`;host.querySelector('#retry-results')?.addEventListener('click',()=>results(host,loadData));return;}if(!host.isConnected)return;
 const combined=data.tables.torch_native_summary.concat(data.tables.cuthbert_native_summary.map(row=>({...row,provider:'cuthbert',method:row.stop_gradient?'systematic_stop':'systematic'})));
 function render(){const schema=resultSchemas[tab],all=tab==='gradient'?combined:data.tables[schema.table],providers=[...new Set(all.map(r=>r.provider??'particles'))];host.innerHTML=`<div class="lab"><div class="lab-heading"><strong>Measured results explorer</strong><span>RECORDED CPU DATA</span></div><div class="tabs" role="group" aria-label="Result dataset">${Object.entries(resultSchemas).map(([key,s])=>`<button class="tab-button ${key===tab?'active':''}" aria-pressed="${key===tab}" data-tab="${key}">${s.label}</button>`).join('')}</div><div class="lab-controls">${schema.cases?select('Task / cloud','results-case',schema.cases,schema.cases[0][0]):''}${select('Particles N','results-n',(tab==='learning'?[128]:[32,128,512,2048]).map(n=>[n,n]),128)}${tab==='static'?select('Dimension d','results-dim',[[1,'1D'],[2,'2D'],[4,'4D']],2):''}${select('Provider','results-provider',[['all','All providers'],...providers.map(p=>[p,providerNames[p]??p])],'all')}${select('Metric','results-metric',schema.metrics,schema.metrics[0][0])}${tab==='static'?select('Error axis','results-scale',[['linear','Linear'],['log','Logarithmic']],'linear'):''}</div><div class="result-data-note">${schema.caption}</div><div class="lab-body" id="results-plot"></div><div class="lab-status" id="results-status"></div><div class="table-scroll" style="margin:0;border-radius:0;border-left:0;border-right:0"><table><thead><tr><th>Provider / method</th><th id="metric-heading">Metric</th><th>95% half-width</th><th>Successful / attempted</th><th>Failure rate</th></tr></thead><tbody id="results-table"></tbody></table></div><div class="result-download"><a id="result-summary-download" href="downloads/${schema.table==='native_gradients'?'torch_native_summary':schema.table}.csv" download>Download full summary CSV ↓</a><button class="text-button" id="filtered-download">Download this selection ↓</button></div></div>`;host.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render();});bindInputs(host,update);update();}
 function update(){const schema=resultSchemas[tab],metric=host.querySelector('#results-metric').value,metricLabel=schema.metrics.find(m=>m[0]===metric)[1],n=+host.querySelector('#results-n').value,provider=host.querySelector('#results-provider').value,all=tab==='gradient'?combined:data.tables[schema.table],kind=host.querySelector('#results-case')?.value,dim=+host.querySelector('#results-dim')?.value;let rows=all.filter(r=>r.n===n&&(provider==='all'||(r.provider??'particles')===provider)&&(!schema.caseKey||r[schema.caseKey]===kind)&&(tab!=='static'||r.dim===dim));rows=rows.sort((a,b)=>{const aa=a[metric],bb=b[metric];if(aa===null||aa===undefined)return 1;if(bb===null||bb===undefined)return-1;return aa-bb;});const available=rows.filter(r=>Number.isFinite(r[metric])),ciKey=metric.endsWith('_mean')?metric.replace(/_mean$/,'_ci95_half'):null;const label=r=>`${r.provider??'particles'}/${r.method}`,providerIndex=p=>Object.keys(providerNames).indexOf(p);let visualization='';if(tab==='static'){const logY=host.querySelector('#results-scale').value==='log';visualization=plot({series:available.filter(r=>r.forward_ms_mean>0).map(r=>({name:label(r),points:[[r.forward_ms_mean,r[metric]]],type:'scatter',radius:r.provider==='custom'?6:4,color:colors[Math.max(0,providerIndex(r.provider))%colors.length],labels:[`${label(r)} · ${r.trials} trials`]})),xLabel:'Serial forward time (ms)',yLabel:metricLabel,logX:true,logY,height:340})+legend([...new Set(available.map(r=>r.provider))].map(p=>[providerNames[p],colors[Math.max(0,providerIndex(p))%colors.length]]));}else if(metric==='loglik_bias'){visualization=plot({series:available.map((r,i)=>({name:label(r),type:'scatter',points:[[i+1,r[metric]]],radius:4,color:colors[Math.max(0,providerIndex(r.provider))%colors.length]})),xLabel:'Row in sorted table below',yLabel:metricLabel,height:300});}else visualization=barPlot(available.map(r=>({label:label(r),value:r[metric],interval:ciKey?r[ciKey]??0:0,color:r.provider==='custom'?colors[0]:colors[1]})),metricLabel);host.querySelector('#results-plot').innerHTML=available.length?visualization:'<p class="toy-caption">No available measurements for this selection. Expensive methods use smaller grids; exact Kalman posterior errors apply only to the linear model.</p>';host.querySelector('#metric-heading').textContent=metricLabel;host.querySelector('#results-table').innerHTML=rows.map(r=>{const success=r.successful_trials??r.trials;return`<tr class="result-row ${r.provider==='custom'?'result-highlight':''}"><td>${esc(label(r))}</td><td class="number-cell">${fmt(r[metric])}</td><td class="number-cell">${fmt(ciKey?r[ciKey]:NaN)}</td><td class="number-cell">${success} / ${r.trials}</td><td class="number-cell">${fmt(100*(r.failure_rate??0))}%</td></tr>`;}).join('');host.querySelector('#results-status').textContent=`${rows.length} result rows · ${available.length} have this metric. Missing values remain unavailable. Accuracy means condition on successful trials. ${tab==='static'?'Hover a point to identify its method. The table preserves zero values omitted by a log axis.':''}`;host.querySelector('#filtered-download').onclick=()=>{if(!rows.length)return;const keys=Object.keys(rows[0]),csv=[keys.join(','),...rows.map(row=>keys.map(k=>`"${String(row[k]??'').replaceAll('"','""')}"`).join(','))].join('\n'),blob=new Blob([csv],{type:'text/csv'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`resampler-${tab}-N${n}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
 render();}

export function hero(host){const{x,w}=S.mixture(80,2.4,.7,47),y=S.eigen1(x,w),input=histogram(x,w,-5,5,50),output=histogram(y,uniform(y),-5,5,50);host.innerHTML=plot({series:[{name:'Weighted input',points:input,type:'bar',color:colors[1]},{name:'Affine output',points:output,color:colors[0]}],xLabel:'Particle position',yLabel:'Probability density',xDomain:[-5,5],yDomain:[0,1.1*Math.max(...input.map(p=>p[1]),...output.map(p=>p[1]))],height:250,title:'A bimodal weighted input and an affine output with matching mean and variance'})+`<div class="hero-caption"><span><b style="color:${colors[1]}">■</b> Weighted input &nbsp; <b style="color:${colors[0]}">━</b> Affine output</span><span>Same mean and variance. Different shape. <a href="#/limits">Explore →</a></span></div>`;}
export function mountLab(name,host,loadData){if(name.startsWith('paper-'))return mountPaperFigure(name,host);const lab={weights,classical,eigen,mixture,gradient,filter,results}[name];return lab?lab(host,loadData):mountAdvancedLab(name,host,loadData);}
